from typing import List


def solution(paragraphs: List[List[str]], aligns: List[str], width: int) -> List[str]:
    border = '*' * (width + 2)
    out = [border]
    for words, align in zip(paragraphs, aligns):
        lines, cur = [], []
        cur_len = 0
        for w in words:
            need = len(w) + (1 if cur else 0)
            if cur and cur_len + need > width:
                lines.append(' '.join(cur))
                cur, cur_len = [w], len(w)
            else:
                cur.append(w)
                cur_len += need
        if cur:
            lines.append(' '.join(cur))
        for line in lines:
            body = line.ljust(width) if align == 'LEFT' else line.rjust(width)
            out.append('*' + body + '*')
    out.append(border)
    return out
